async function deleteStudents(c,students){const operations=students.map(student=>({id:student.deleteId||crypto.randomUUID(),type:'student-delete',ctx:ctx(c),nim:student.nim,base:{nama:student.nama}}));await change(s=>{if(s.profile?.role!=='teacher')throw Error('Masuk dengan akun dosen.');for(const op of operations){if(!s.outbox.some(o=>o.id===op.id))s.outbox.push(op);applyOp(s,op);}return s;});void sync();return operations;}
async function sync(){window.WA.lastError='';if(syncing){syncAgain=true;return syncing;}syncAgain=false;syncing=(async()=>{const s=await get();if(!s.token||!navigator.onLine)return;try{const active=s.outbox.filter(o=>!o.problem).slice(0,100);active.forEach(o=>inFlight.add(o.id));const r=await api(active.length?'sync':'snapshot',active.length?{operations:active.slice(0,100)}:{knownTag:s.snapshot.tag||''});dispatchPush(s);if(r.unchanged){await change(current=>{current.snapshot.serverTime=r.serverTime;current.snapshot.receivedAt=Date.now();return current;});return;}await change(current=>{const results=new Map((r.results||[]).map(x=>[x.id,x]));current.outbox=current.outbox.filter(o=>results.get(o.id)?.status!=='success');for(const o of current.outbox){const result=results.get(o.id);if(result&&['conflict','error'].includes(result.status))o.problem=result;}r.snapshot.receivedAt=Date.now();current.snapshot=r.snapshot;current.profile=r.snapshot.profile;for(const o of current.outbox){const predecessor=active.find(a=>results.get(a.id)?.status==='success'&&a.type===o.type&&a.scope===o.scope&&(o.type==='document'?a.kind===o.kind:o.type==='mark'?a.nim===o.nim&&a.slot===o.slot:false));if(predecessor&&!results.has(o.id)&&!o.problem){const remote=o.type==='document'?r.snapshot.documents.find(x=>x.scope===o.scope&&x.kind===o.kind):r.snapshot.marks.find(x=>x.scope===o.scope&&x.nim===o.nim&&x.slot===o.slot);o.baseRevision=remote?.revision||0;}applyOp(current,o);}return current;});}catch(e){if(e.code==='AUTH_REQUIRED'){await change(s=>{s.authExpired=true;return s;});}window.WA.lastError=e.message;}finally{inFlight.clear();}})().finally(()=>{syncing=null;if(syncAgain){syncAgain=false;void sync();}});return syncing;}
