function now(s){return Date.now()+(s?.snapshot?.serverTime&&s?.snapshot?.receivedAt?s.snapshot.serverTime-s.snapshot.receivedAt:0);}
function day(t=Date.now()){return new Intl.DateTimeFormat('sv-SE',{timeZone:'Asia/Jakarta',year:'numeric',month:'2-digit',day:'2-digit'}).format(t);}
async function startSession(c,course,slot,minutes){if(!course.trim())throw Error('Isi mata kuliah untuk sesi absen ini.');if(!Number.isFinite(minutes)||minutes<=0||minutes>1440)throw Error('Isi durasi antara 1 dan 1440 menit.');const s=await get(),sc=await scope(c,course),old=s.snapshot.sessions.find(x=>x.scope===sc&&x.slot===Number(slot)),t=now(s);if(old&&old.day!==day(t))throw Error('Pertemuan ini sudah digunakan. Pilih pertemuan berikutnya.');if(old&&old.teacher_id!==s.profile.device)throw Error('Reset dilakukan dari perangkat pembuat QR.');const deadline=t+minutes*60000;if(day(t)!==day(deadline))throw Error('Batas absen harus berakhir pada tanggal yang sama.');const data={v:1,type:'session',device:s.profile.device,id:old?.id||crypto.randomUUID(),ctx:ctx(c),matkul:course.trim(),slot:Number(slot),starts:t,deadline,ends:deadline,version:(old?.version||0)+1,nonce:b64(crypto.getRandomValues(new Uint8Array(24))).replaceAll('-','a').replaceAll('_','b')};data.nonce=Array.from(crypto.getRandomValues(new Uint8Array(24)),v=>v.toString(16).padStart(2,'0')).join('');const challenge=await seal(data),session={...data,scope:sc,day:day(t),challenge,teacher_id:s.profile.device,roster:s.snapshot.roster.filter(x=>sameCtx(x,c)).map(x=>x.nim)};await queue({type:'session',challenge,session});return session;}
